  3372	void sf32lb_sd_reclock(void)
  3373	{
  3374	  uint32_t div_before;
  3375	  uint32_t div_after;
  3376	  bool held;
  3377	
  3378	  if (!g_sd_initialized)
  3379	    {
  3380	      return;
  3381	    }
  3382	
  3383	  held = g_sd_clk_held;
  3384	  g_sd_clk_held = false;
  3385	
  3386	  if (!held)
  3387	    {
  3388	      nxmutex_lock(&g_sd_lock);
  3389	      div_before = ((hwp_sdmmc1->CLKCR & SD_CLKCR_DIV_Msk) >> SD_CLKCR_DIV_Pos) + 1u;
  3390	    }
  3391	  else
  3392	    {
  3393	      /* 停钟时 DIV 字段读到的是 0，用 clk_hold 存下来的真值。 */
  3394	      div_before = g_sd_div_held_before;
  3395	    }
  3396	
  3397	  sd1_set_clock(g_sd_bus_hz);  /* 结尾清 STOP_CLK，即放钟 */
  3398	  div_after = ((hwp_sdmmc1->CLKCR & SD_CLKCR_DIV_Msk) >> SD_CLKCR_DIV_Pos) + 1u;
  3399	  nxmutex_unlock(&g_sd_lock);
  3400	
  3401	  /* 每次 DVFS 跳档都会走到这里，DIV 必变。这行是"跳档 ↔ SD 时钟"的
