  3408	   * 在切换之前测量，所以是可信的。
  3409	   */
  3410	  if (held)
  3411	    {
  3412	      syslog(LOG_INFO,
  3413	             "SD: clk div %lu -> %lu (SDCLK %lu kHz) wait=%u ms\n",
  3414	             (unsigned long)div_before, (unsigned long)div_after,
  3415	             (unsigned long)(g_sd_bus_hz / 1000u),
  3416	             (unsigned)g_sd_hold_wait_ms);
  3417	    }
  3418	  else if (div_before != div_after)
  3419	    {
  3420	      syslog(LOG_INFO, "SD: clk div %lu -> %lu (SDCLK %lu kHz)\n",
  3421	             (unsigned long)div_before, (unsigned long)div_after,
  3422	             (unsigned long)(g_sd_bus_hz / 1000u));
  3423	    }
  3424	}
